SP = "/tmp/claude-1000/-home-ucak-projects-llm-tui/fb22d2c9-515c-49f3-85f0-81dac591893a/scratchpad"
data = json.load(open(f"{SP}/ctx.json"))
msgs = data["messages"]

ROLE = {"HumanMessage": ("human", "You"), "AIMessage": ("assistant", "Assistant"), "ToolMessage": ("tool", "Tool result")}

def e(s): return html.escape(str(s))

def size(m):
    if m["kind"] == "AIMessage":
        return sum(len(json.dumps(b)) for b in m.get("blocks", []))
    return len(m.get("content", ""))

totals = {}
for m in msgs:
    totals[m["kind"]] = totals.get(m["kind"], 0) + size(m)
grand = sum(totals.values())

# citation audit
retrieved, cited, fabricated = set(), set(), set()
for m in msgs:
    if m["kind"] == "ToolMessage":
        retrieved |= set(re.findall(r"p\.(\d+)", m["content"]))
    if m["kind"] == "AIMessage":
        txt = "".join(b.get("text", "") for b in m.get("blocks", []) if b.get("type") == "text")
        if txt:
            c = set(re.findall(r"p\.(\d+)", txt))
            cited |= c
            fabricated |= (c - retrieved)

parts = []
for m in msgs:
    cls, label = ROLE[m["kind"]]
    n = m["i"]
    body = []

    if m["kind"] == "HumanMessage":
        body.append(f'<div class="prose">{e(m["content"])}</div>')

    elif m["kind"] == "ToolMessage":
        body.append(
            f'<div class="kv"><span>status</span><code class="ok">{e(m["status"])}</code>'
            f'<span>tool</span><code>{e(m["name"])}</code>'
            f'<span>replies to</span><code>{e(m["tool_call_id"])}</code></div>')
        chunks = re.split(r"\n\n---\n\n", m["content"])
        body.append(f'<div class="blk-label">{len(chunks)} passages returned</div>')
        for ch in chunks:
            head, _, rest = ch.partition("\n")
            body.append(
                f'<div class="passage"><div class="cite">{e(head)}</div>'
                f'<pre>{e(rest)}</pre></div>')

    else:
        for b in m.get("blocks", []):
            t = b.get("type")
            if t == "reasoning":
                body.append(f'<div class="blk reasoning"><div class="blk-label">reasoning block</div>'
                            f'<div class="prose dim">{e(b.get("reasoning",""))}</div></div>')
            elif t == "text":
                body.append(f'<div class="blk"><div class="blk-label">text block</div>'
                            f'<div class="prose">{e(b.get("text",""))}</div></div>')
            elif t == "tool_call":
                body.append(
                    f'<div class="blk call"><div class="blk-label">tool_call block</div>'
                    f'<div class="kv"><span>name</span><code>{e(b.get("name"))}</code>'
                    f'<span>id</span><code>{e(b.get("id"))}</code></div>'
                    f'<pre class="args">{e(json.dumps(b.get("args"), indent=2))}</pre></div>')
            elif t == "invalid_tool_call":
                body.append(
                    f'<div class="blk bad"><div class="blk-label warn">invalid_tool_call block</div>'
                    f'<div class="kv"><span>error</span><code class="no">{e(b.get("error"))}</code></div>'
                    f'<pre class="args">{e(b.get("args"))}</pre></div>')
        tc, itc = len(m.get("tool_calls") or []), len(m.get("invalid_tool_calls") or [])
        body.append(f'<div class="kv"><span>.tool_calls</span><code class="{"ok" if tc else ""}">{tc}</code>'
                    f'<span>.invalid_tool_calls</span><code class="{"no" if itc else "ok"}">{itc}</code></div>')

    types = ",".join(b.get("type", "?") for b in m.get("blocks", [])) if m["kind"] == "AIMessage" else ""
    parts.append(f'''<article class="msg {cls}">
  <header class="msg-head">
    <span class="idx">{n}</span>
    <span class="role">{label}</span>
    <span class="meta">{e(m["kind"])}{" &middot; " + e(types) if types else ""} &middot; {size(m):,} chars</span>
  </header>
  {"".join(body)}
</article>''')

bar = "".join(
    f'<div class="seg {ROLE[k][0]}" style="width:{v/grand*100:.2f}%" title="{k}: {v:,} chars"></div>'
    for k, v in totals.items())
legend = "".join(
    f'<span class="lg"><i class="dot {ROLE[k][0]}"></i>{ROLE[k][1]} <b>{v/grand*100:.0f}%</b> <em>{v:,}</em></span>'
    for k, v in totals.items())

