def main() -> None:
    parser = argparse.ArgumentParser(description="Render a checkpointed thread as HTML.")
    parser.add_argument("thread_id", nargs="?", help="thread to render (default: most recent)")
    parser.add_argument("--list", action="store_true", help="list threads and exit")
    parser.add_argument("-o", "--out", default="context.html", help="output file")
    args = parser.parse_args()

    connection = sqlite3.connect(SQLITE_DB_PATH, check_same_thread=False)
    threads = load_threads(connection)
    if not threads:
        sys.exit("no threads in the checkpoint database")

    if args.list:
        for ts, thread_id, count in threads:
            print(f"{ts[:19]}  {thread_id}  {count} messages")
        return

    thread_id = args.thread_id or threads[-1][1]
    saver = SqliteSaver(connection)
    tup = saver.get_tuple({"configurable": {"thread_id": thread_id}})
    if not tup:
        sys.exit(f"no checkpoint for thread {thread_id}")

    messages = tup.checkpoint["channel_values"].get("messages", [])
    with open(args.out, "w") as f:
        f.write(build_page(thread_id, messages))
    print(f"wrote {args.out}  ({thread_id}, {len(messages)} messages)")


if __name__ == "__main__":
    main()
